-- gen619: 10 zone cambiate, 21 tessere
-- e7aecade7aa6a5d7ef3ad9b78edda8b7 (1013583) → c5cffb144af4c8afa72927802ab50912 (1022364)

  on conflict (key) do update set value=excluded.value;


-- il cancello, PRIMA di scrivere
select md5(string_agg(value, '' order by key)) as md5_ricomposto,
       length(string_agg(value, '' order by key)) as len_ricomposto,
       md5(string_agg(value, '' order by key)) = 'c5cffb144af4c8afa72927802ab50912' as combacia
from kv_store where key like 'tmp:gen619:p%';

update kv_store set value = (select string_agg(value, '' order by key) from kv_store where key like 'tmp:gen619:p%')
where key='app:jsx:src'
  and md5(value) = 'e7aecade7aa6a5d7ef3ad9b78edda8b7'
  and (select md5(string_agg(value, '' order by key)) from kv_store where key like 'tmp:gen619:p%') = 'c5cffb144af4c8afa72927802ab50912';

update kv_store set value = '{"len":1022364,"ver":"gen-6.19"}'
where key='app:jsx:meta'
  and (select md5(value) from kv_store where key='app:jsx:src') = 'c5cffb144af4c8afa72927802ab50912';

delete from kv_store where key like 'tmp:gen619:p%';
